// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.connectivity.diimport android.content.Contextimport androidx.room.Databaseimport androidx.room.Roomimport androidx.room.RoomDatabaseimport androidx.room.TypeConvertersimport androidx.sqlite.db.SupportSQLiteDatabaseimport com.roshan.persona.connectivity.call.STARTER_SPAM_ENTRIESimport com.roshan.persona.connectivity.call.SpamNumberDaoimport com.roshan.persona.connectivity.call.SpamNumberEntityimport com.roshan.persona.connectivity.call.SpamNumberFtsEntityimport com.roshan.persona.connectivity.call.SpamTypeConvertersimport com.roshan.persona.connectivity.contact.ContactFtsDaoimport com.roshan.persona.connectivity.contact.ContactFtsEntityimport com.roshan.persona.connectivity.recording.ContactRecordingPolicyEntityimport com.roshan.persona.connectivity.recording.RecordingPolicyConvertersimport com.roshan.persona.connectivity.recording.RecordingPolicyDaoimport kotlinx.coroutines.CoroutineScopeimport kotlinx.coroutines.Dispatchersimport kotlinx.coroutines.SupervisorJobimport kotlinx.coroutines.launchimport timber.log.Timber/** * NOUS — Connectivity Room Database (Module 11 v3 — P1). * * Hosts: *  - [SpamNumberEntity] + [SpamNumberFtsEntity] — Room-backed spam DB *    (replaces [InMemorySpamDatabase]). *  - [ContactRecordingPolicyEntity] — per-contact recording policy store. *  - [ContactFtsEntity] — FTS4 mirror of ContactsContract for sub-20ms search. * * ## Encryption * * The DB is created with the **plain Room** helper (no SQLCipher here) — * Module 11's spam/policy/contact-FTS data is NOT considered sensitive * enough to warrant encryption. (Spam classifications are public knowledge; * contact names are already in the system ContactsContract which is shared * with any app that has READ_CONTACTS.) Call recordings ARE encrypted * via [com.roshan.persona.connectivity.recording.Aes256Encryptor] — but * those are file-level encrypted, not DB-level. * * If the project later decides this DB should also be SQLCipher-encrypted, * swap `Room.databaseBuilder(...)` for `Room.databaseBuilder(...).openHelperFactory(SupportFactory(passphrase))` * — the schema is identical. * * ## Pre-population * * On first creation, the [STARTER_SPAM_ENTRIES] are inserted so the user * has spam protection out-of-the-box (Strategy §"SpamDetectorEngine" — * "starter list of known spam patterns"). */@Database(    entities = [        SpamNumberEntity::class,        SpamNumberFtsEntity::class,        ContactRecordingPolicyEntity::class,        ContactFtsEntity::class,    ],    version = 1,    exportSchema = false,)@TypeConverters(    SpamTypeConverters::class,    RecordingPolicyConverters::class,)abstract class ConnectivityDatabase : RoomDatabase() {    abstract fun spamNumberDao(): SpamNumberDao    abstract fun recordingPolicyDao(): RecordingPolicyDao    abstract fun contactFtsDao(): ContactFtsDao    companion object {        const val DATABASE_NAME = "nous-connectivity.db"        /**         * Build the DB with a callback that pre-populates the spam table         * on first creation only.         */        fun build(context: Context): ConnectivityDatabase {            val scope = CoroutineScope(SupervisorJob() + Dispatchers.IO)            return Room.databaseBuilder(                context,                ConnectivityDatabase::class.java,                DATABASE_NAME,            )                .fallbackToDestructiveMigrationOnDowngrade()                .addCallback(object : Callback() {                    override fun onCreate(db: SupportSQLiteDatabase) {                        super.onCreate(db)                        // Pre-populate starter spam entries on first launch.                        scope.launch {                            try {                                STARTER_SPAM_ENTRIES.forEach { entry ->                                    db.execSQL(                                        """                                        INSERT OR REPLACE INTO spam_numbers                                        (number, level, source, reason, confidence, last_updated)                                        VALUES (?, ?, ?, ?, ?, ?)                                        """.trimIndent(),                                        arrayOf(                                            entry.number,                                            entry.level.name,                                            entry.source.name,                                            entry.reason,                                            entry.confidence,                                            entry.lastUpdated,                                        ),                                    )                                }                                Timber.tag("ConnectivityDatabase")                                    .i("Pre-populated ${STARTER_SPAM_ENTRIES.size} starter spam entries.")                            } catch (t: Throwable) {                                Timber.tag("ConnectivityDatabase")                                    .e(t, "Pre-populate spam entries failed")                            }                        }                    }                })                .build()        }    }}